div.script:

const gamesList = [
  { id: 'cyberclicker', title: 'Rice Grain Clicker', cat: 'clicker', icon: '🍚', bg: '#0284c7' },
  { id: 'trafficracer', title: 'Highway Racer 2D', cat: 'driving', icon: '🏎️', bg: '#dc2626' },
  { id: 'targetshooter', title: 'Target Sniper 2D', cat: 'action', icon: '🎯', bg: '#16a34a' },
  { id: 'memorymatch', title: 'Memory Grid Challenge', cat: 'puzzle', icon: '🧩', bg: '#9333ea' }
];

let currentCategory = 'all';

function renderGames() {
  const grid = document.getElementById('gamesGrid');
  const searchTerm = document.getElementById('searchBox').value.toLowerCase();
  grid.innerHTML = '';

  gamesList.forEach(game => {
    const matchesCat = currentCategory === 'all' || game.cat === currentCategory;
    const matchesSearch = game.title.toLowerCase().includes(searchTerm);

    if (matchesCat && matchesSearch) {
      const card = document.createElement('div');
      card.className = 'game-card';
      card.onclick = () => launchGame(game.id);
      card.innerHTML = `
        <div class="game-icon" style="background: ${game.bg};">${game.icon}</div>
        <div class="game-title">${game.title}</div>
        <div class="game-tag">${game.cat.toUpperCase()}</div>
      `;
      grid.appendChild(card);
    }
  });
}

function setCategory(cat, el) {
  currentCategory = cat;
  document.querySelectorAll('.chip').forEach(c => c.classList.remove('active'));
  el.classList.add('active');
  renderGames();
}

function filterGames() {
  renderGames();
}

function toggleMenu() {
  document.getElementById('sideMenu').classList.toggle('open');
}

function launchGame(id) {
  const overlay = document.getElementById('gameOverlay');
  const frame = document.getElementById('arcadeFrame');
  const title = document.getElementById('overlayTitle');

  overlay.classList.add('active');

  if (id === 'cyberclicker') {
    title.textContent = "Rice Grain Clicker";
    frame.innerHTML = `
      <div style="text-align:center;">
        <h2 id="clkScore" style="font-size: 2rem;">Rice Collected: 0</h2>
        <button onclick="addClick()" style="padding: 20px 40px; font-size: 1.5rem; background: #38bdf8; border: none; border-radius: 50%; color: #0f172a; font-weight: bold; cursor: pointer;">GATHER RICE 🍚</button>
      </div>
    `;
    window.clickScore = 0;
    window.addClick = function() {
      window.clickScore += 1;
      document.getElementById('clkScore').textContent = "Rice Collected: " + window.clickScore;
    };
  } else if (id === 'trafficracer') {
    title.textContent = "Highway Racer 2D";
    frame.innerHTML = `
      <div style="text-align:center;">
        <p>Use LEFT / RIGHT Keys to Avoid Traffic!</p>
        <div id="laneArea" style="width: 200px; height: 300px; background: #334155; position: relative; margin: 0 auto; border-radius: 10px; overflow: hidden;">
          <div id="playerCar" style="width: 30px; height: 50px; background: #38bdf8; position: absolute; bottom: 10px; left: 85px; border-radius: 6px;"></div>
        </div>
      </div>
    `;
    let pos = 85;
    window.onkeydown = function(e) {
      if (e.key === 'ArrowLeft' && pos > 10) pos -= 20;
      if (e.key === 'ArrowRight' && pos < 160) pos += 20;
      const car = document.getElementById('playerCar');
      if (car) car.style.left = pos + 'px';
    };
  } else if (id === 'targetshooter') {
    title.textContent = "Target Sniper 2D";
    frame.innerHTML = `
      <div style="text-align:center;">
        <h3 id="sniperScore">Targets Hit: 0</h3>
        <div id="targetBox" style="width: 300px; height: 250px; background: #1e293b; position: relative; margin: 0 auto; border-radius: 12px; cursor: crosshair;">
          <div id="targetDot" onclick="hitTarget()" style="width: 35px; height: 35px; background: #ef4444; border-radius: 50%; position: absolute; top: 100px; left: 130px;"></div>
        </div>
      </div>
    `;
    window.snipes = 0;
    window.hitTarget = function() {
      window.snipes += 1;
      document.getElementById('sniperScore').textContent = "Targets Hit: " + window.snipes;
      const dot = document.getElementById('targetDot');
      dot.style.top = Math.floor(Math.random() * 200) + 'px';
      dot.style.left = Math.floor(Math.random() * 250) + 'px';
    };
  } else {
    title.textContent = "Memory Grid Challenge";
    frame.innerHTML = `<h3 style="color: #cbd5e1;">Memory puzzle active! Match the tiles.</h3>`;
  }
}

function closeGame() {
  document.getElementById('gameOverlay').classList.remove('active');
  document.getElementById('arcadeFrame').innerHTML = '';
  window.onkeydown = null;
}

function saveProgress() {
  alert('Adventurerice progress saved!');
  toggleMenu();
}

function resetProgress() {
  if (confirm('Reset portal settings?')) {
    alert('Progress reset.');
    toggleMenu();
  }
}

renderGames();
